import{_ as a,o as t,c as r,a2 as d}from"./chunks/framework.Bx7X8BVG.js";const u=JSON.parse('{"title":"桌面端：安装、使用与升级","description":"","frontmatter":{},"headers":[],"relativePath":"guide/desktop.md","filePath":"guide/desktop.md","lastUpdated":1791444273000}'),n={name:"guide/desktop.md"};function o(l,e,i,s,c,h){return t(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="桌面端-安装、使用与升级" tabindex="-1">桌面端：安装、使用与升级 <a class="header-anchor" href="#桌面端-安装、使用与升级" aria-label="Permalink to &quot;桌面端：安装、使用与升级&quot;">​</a></h1><p>当前版本 <strong>v1.8.2</strong>。内置 Tauri 桌面界面、Node、本地管理服务、cloudflared 和生产依赖，<strong>不需要 Docker，也不需要另装 Node</strong>。Windows 界面使用系统 WebView2；系统缺少时，安装器的 bootstrapper 可能需要联网安装它，不能将这种环境宣传为完全离线安装。</p><h2 id="下载与适用系统" tabindex="-1">下载与适用系统 <a class="header-anchor" href="#下载与适用系统" aria-label="Permalink to &quot;下载与适用系统&quot;">​</a></h2><p>以下大小来自 v1.8.2 Release（2026-10-07 核对，按 MiB 四舍五入，与 GitHub 的显示一致）：</p><table tabindex="0"><thead><tr><th>系统/架构</th><th>安装包</th><th>大小</th></tr></thead><tbody><tr><td>Windows x64</td><td><a href="https://github.com/lieren2012/cloudflare-tunnel-manager/releases/download/v1.8.2/CF.Tunnel.Manager_1.8.2_x64-setup.exe" target="_blank" rel="noreferrer">EXE</a></td><td>38.3 MB</td></tr><tr><td>Windows x64</td><td><a href="https://github.com/lieren2012/cloudflare-tunnel-manager/releases/download/v1.8.2/CF.Tunnel.Manager_1.8.2_x64_en-US.msi" target="_blank" rel="noreferrer">MSI</a></td><td>54.5 MB</td></tr><tr><td>macOS Apple Silicon</td><td><a href="https://github.com/lieren2012/cloudflare-tunnel-manager/releases/download/v1.8.2/CF.Tunnel.Manager_1.8.2_aarch64.dmg" target="_blank" rel="noreferrer">DMG</a></td><td>57.5 MB</td></tr><tr><td>Linux amd64</td><td><a href="https://github.com/lieren2012/cloudflare-tunnel-manager/releases/download/v1.8.2/CF.Tunnel.Manager_1.8.2_amd64.deb" target="_blank" rel="noreferrer">DEB</a></td><td>65.2 MB</td></tr></tbody></table><p>没有 v1.8.2 AppImage、Intel Mac、Windows ARM64 或 Linux ARM 桌面包。历史 v1.8.0 的小体积包存在服务启动问题，不应作为当前使用入口。</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>建议 Windows 10/11 x64，普通用户下载 EXE，安装后启动 CF Tunnel Manager。Windows 版本兼容性未逐个验收；不要将 GitHub Windows runner 测试描述成所有 Windows 版本都已实测。MSI 适用于需要该格式的部署场景。</p><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>确认“关于本机”显示 Apple M 系列芯片，下载 DMG，打开并将应用复制到 Applications。当前构建未配置开发者签名和 notarization；系统可能提示无法验证开发者，需遵循 macOS 的安全策略，不能将它视为已签名安装包。项目配置的最低系统版本不等于每个旧系统版本已通过测试。</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>确认 <code>uname -m</code> 为 <code>x86_64</code>。在支持 WebKitGTK 4.1 的 Debian/Ubuntu 系发行版安装：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./CF.Tunnel.Manager_1.8.2_amd64.deb</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>包管理器可能需要联网安装 GTK/WebKit 依赖。其他发行版、桌面环境和旧版本未逐个测试。需要无图形界面长期运行时，请使用 Docker 版。</p><h2 id="首次启动" tabindex="-1">首次启动 <a class="header-anchor" href="#首次启动" aria-label="Permalink to &quot;首次启动&quot;">​</a></h2><p>程序启动本地服务，检查 <code>/api/auth/state</code> 成功后才打开窗口。</p><ul><li>新数据目录：显示“创建管理员账户”。</li><li>已有数据：显示登录；保留原用户名和密码。</li><li>无法打开窗口：查看下方 service.log，不能靠无限等待解决。</li></ul><p>注册面板账户后，按 <a href="/cloudflare-tunnel-manager/guide/#配置-cloudflare">快速开始</a> 配置 Cloudflare Token、创建隧道和路由。</p><h2 id="转发本地服务" tabindex="-1">转发本地服务 <a class="header-anchor" href="#转发本地服务" aria-label="Permalink to &quot;转发本地服务&quot;">​</a></h2><p>例如你的电脑已经运行 <code>http://127.0.0.1:8080</code>，把域名路由到这个地址即可；运行服务与桌面端需要在同一台电脑，或填写桌面端可达的局域网 IP。</p><p>**桌面端启动的是管理服务和 cloudflared，不会替你启动业务网站。**局域网访问、公网 HTTPS、业务登录均需分别验证。</p><h2 id="端口和数据目录" tabindex="-1">端口和数据目录 <a class="header-anchor" href="#端口和数据目录" aria-label="Permalink to &quot;端口和数据目录&quot;">​</a></h2><p>桌面版绑定 <code>127.0.0.1</code>，Web/API/MCP 端口动态选择，不固定为 19090/19092/19093，也不直接给其他局域网设备提供面板。实际端口见 service.log。Docker 教程里的固定端口命令不能直接套用。</p><table tabindex="0"><thead><tr><th>系统</th><th>默认应用目录</th></tr></thead><tbody><tr><td>Windows</td><td><code>%APPDATA%\\com.lieren2012.cf-tunnel-manager</code></td></tr><tr><td>macOS</td><td><code>~/Library/Application Support/com.lieren2012.cf-tunnel-manager</code></td></tr><tr><td>Linux</td><td><code>$XDG_DATA_HOME/com.lieren2012.cf-tunnel-manager</code>，通常为 <code>~/.local/share/com.lieren2012.cf-tunnel-manager</code></td></tr></tbody></table><p>目录下 <code>data/</code> 保存账号/隧道/凭据，<code>service.log</code> 保存启动日志。Docker data 不会自动导入桌面端；迁移前停止两个实例、备份并核对数据结构，避免同时操作同一配置。</p><h2 id="升级与卸载" tabindex="-1">升级与卸载 <a class="header-anchor" href="#升级与卸载" aria-label="Permalink to &quot;升级与卸载&quot;">​</a></h2><ol><li>关闭旧应用并备份应用目录中的 data。</li><li>从 Release 下载对应系统架构的新包，覆盖安装。</li><li>启动后登录原账号，核对隧道与配置。</li></ol><p>当前桌面版<strong>没有应用内自动更新器</strong>。面板中的 Git 源码更新机制针对 Docker/源码部署，不能用来升级桌面安装包。卸载桌面程序与删除本地 data、删除 Cloudflare 云端隧道是不同操作；清理数据前先备份。</p><h2 id="当前边界" tabindex="-1">当前边界 <a class="header-anchor" href="#当前边界" aria-label="Permalink to &quot;当前边界&quot;">​</a></h2><p>电脑休眠、断网和关闭程序可能影响连接；当前不保证系统后台常驻或开机启动。Windows MSI 解包后的启动/注册/重启账号测试已通过；macOS/Linux 通过运行资源测试和打包，尚未完成各平台安装界面全流程验收。完整证据见 <a href="/cloudflare-tunnel-manager/guide/verification">验证记录</a>。</p>',30)])])}const b=a(n,[["render",o]]);export{u as __pageData,b as default};
